# The SQL and PowerShell commands named ⟦SQL-1⟧ ... ⟦PS-2⟧ are printed in the guide section «دستورهای SQL و PowerShell مدیر فنی» (snippets.py).

SNAP_KEYS = "، ".join("⟦%s⟧" % k for k in ("activeProjects", "cash", "itemsBelowMinimum", "lateProductionOrders", "openNcrs", "openPurchaseOrdersAmount",
                                          "payablesOverdue", "receivablesOpen", "salesBacklog", "salesPipelineValue", "serviceSlaBreaches", "stockValue"))
TECH = "(ویژه‌ی مدیر فنی) "

